WITH exploded AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW EXPLODE(discounts) li AS element) SELECT CASE WHEN element >= 65 THEN 'HIGH' ELSE 'LOW' END AS element_tier, DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, APPROX_PERCENTILE(element, 0.5) AS element_p50, COUNT(*) AS num_rows, APPROX_PERCENTILE(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles FROM exploded GROUP BY CASE WHEN element >= 65 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', effective_from) ORDER BY activity_month DESC NULLS FIRST
